//     d
//    /
//   p
//  / \ 
// o ->c
bool intersect( out vec3 p, in vec3 ro, in vec3 rd, in vec3 c, in float r) {
    float R = sqrt(dot(c-ro,c-ro));
    float max_sin_poc = r / R;
    float cos_poc = dot(rd, normalize(c-ro));
    float sin_poc = sqrt(1.-pow(cos_poc, 2.));
    if (sin_poc > max_sin_poc) {
      return false;
    } else {
      // r*sin_cpd == R * sin_poc
      float sin_cpd = R / r * sin_poc;
      float cos_cpd = sqrt(1.-pow(sin_cpd, 2.));
      // op == t * rd;
      float t = R*cos_poc - r*cos_cpd;
      p = ro + rd * t;
      return true;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col_ray = vec3(1.,1.,1.);
    vec3 col_dark = vec3(0.,0.,0.);
    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = fragCoord/iResolution.xy * 2. - 1.;
    // make it square
    uv.x = uv.x * iResolution.x / iResolution.y;
    // view origin and direction
    vec3 vo = vec3(0.,0.,2.);
    vec3 vd = normalize(vec3(uv, -1.0));
    // rotate view across y axis
    float angle = 3.1415926 * iTime;
    mat3 m = mat3(cos(angle), 0., sin(angle), 0., 1., 0., -sin(angle), 0., cos(angle));
    vo = m * vo;
    vd = m * vd;
    // sphere center and radius
    vec3 sc = vec3(0.,0.,0.);
    float r = 1.;
    // ray
    vec3 ro = vec3(0.,0.,2.);
    vec3 p;
    float fresnel_term = 0.0;
    if (intersect(p, vo, vd, sc, r)) {
        vec3 n = p - sc;
        vec3 rd = normalize(p - ro);
        fresnel_term = clamp(dot(rd, n), 0., 1.);
        fragColor = vec4(col_dark * (1.-fresnel_term) + col_ray * fresnel_term, 1.0);
    } else {
        fragColor = vec4(col_dark, 1.0);
        return;
    }
}
